import{_ as t,c as r,o as s,a2 as a}from"./chunks/framework.DkPtUiZm.js";const m=JSON.parse('{"title":"Suivi des mises à jour","description":"","frontmatter":{},"headers":[],"relativePath":"contribuer/backlog.md","filePath":"contribuer/backlog.md","lastUpdated":1794238461000}'),i={name:"contribuer/backlog.md"};function n(o,e,d,l,c,u){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="suivi-des-mises-a-jour" tabindex="-1">Suivi des mises à jour <a class="header-anchor" href="#suivi-des-mises-a-jour" aria-label="Permalink to &quot;Suivi des mises à jour&quot;">​</a></h1><h2 id="implemente-—-prochaine-publication" tabindex="-1">Implémenté — prochaine publication <a class="header-anchor" href="#implemente-—-prochaine-publication" aria-label="Permalink to &quot;Implémenté — prochaine publication&quot;">​</a></h2><p>Ces éléments sont présents dans le code ; ils ne sont pas encore annoncés comme disponibles sur npm.</p><table tabindex="0"><thead><tr><th>Brique</th><th>Mise à jour exacte</th><th>Utilité</th></tr></thead><tbody><tr><td><code>@sia-ui/realtime-server</code></td><td>Nouveau paquet sans dépendance de production : passerelle structurelle, authentification, salons implicites, autorisation des jointures, accusés et nettoyage.</td><td>Brancher Socket.IO ou un adaptateur sans réécrire les contrôles d’accès aux flux.</td></tr><tr><td>Contrats temps réel</td><td><code>defineTopics</code>, <code>TopicsOf</code>, <code>defineRooms</code>, <code>Publisher</code> et <code>noopPublisher</code>.</td><td>Partager les sujets et charges utiles à la compilation ; injecter un port de publication testable dans le métier.</td></tr><tr><td>Reprise d’événements</td><td>Identifiant opaque, séquence par émetteur, horodatage, journal mémoire borné et <code>ReplayStore</code> injectable.</td><td>Rejouer ce qui a été manqué ou demander explicitement une resynchronisation du salon.</td></tr><tr><td>Diffusion et présence</td><td>Interface <code>Fanout</code> injectable, déduplication des rebonds, présence locale par principal et libération des abonnements.</td><td>Relier plusieurs instances sans choisir un broker ; inspecter les connexions de l’instance.</td></tr><tr><td>Cadence par clé</td><td><code>throttlePerKey</code>, promesses de livraison de dernière valeur, <code>flush</code> et <code>cancel</code>.</td><td>Limiter les flux fréquents sans perdre leur dernière valeur ni cacher les erreurs.</td></tr><tr><td>Client Socket.IO</td><td>Salons référencés, départ au dernier abonné, reprise avec curseur, erreurs de jointure observables, invalidation ciblée et <code>dispose</code>.</td><td>Maintenir les abonnements après coupure et nettoyer les écouteurs sans assertions de types.</td></tr><tr><td>Cache temps réel</td><td><code>createRealtimeBinding&lt;Topics&gt;</code> avec charges utiles contextualisées.</td><td>Supprimer les conversions manuelles des événements quand le contrat partagé est fourni.</td></tr><tr><td>SSE</td><td><code>fetchStreamSource</code> : UTF-8 fragmenté, événements nommés, JSON/texte, reprise <code>Last-Event-ID</code>, bornes mémoire et annulation ; adaptateur serveur <code>createSseServer</code>.</td><td>Utiliser SSE sans supposer un EventSource global ; intégrer son propre framework HTTP.</td></tr><tr><td>Cycle EventSource</td><td>Restauration des callbacks préexistants et retrait des abonnements avec <code>dispose</code>.</td><td>Ne pas écraser durablement les écouteurs de l’application.</td></tr><tr><td>Polling</td><td><code>pollUntil</code> et <code>usePollUntil</code>, délais progressifs, timeout, visibilité injectable, annulation et terminaison par événement.</td><td>Attendre une opération sans appels concurrents ni boucle active en arrière-plan.</td></tr><tr><td>Hook de salon</td><td><code>useRealtimeRoom</code>, nettoyage synchrone/asynchrone et erreur observable.</td><td>Associer le suivi d’un salon au cycle de vie de la vue.</td></tr><tr><td>Téléphones</td><td><code>normalizePhone</code>, <code>toNationalNumber</code>, <code>formatPhone</code> et table de pays injectable.</td><td>Uniformiser stockage E.164, format opérateur et affichage sans base mondiale embarquée.</td></tr><tr><td>Navigation</td><td>Liens web et schémas d’application Google Maps, Waze, Apple Plans ; coordonnées validées.</td><td>Ouvrir un itinéraire depuis des coordonnées avec un repli web.</td></tr><tr><td>Tokens</td><td>Exports JavaScript, preset Tailwind web et preset NativeWind à valeurs concrètes, issus des mêmes tokens.</td><td>Réutiliser les couleurs, espacements et durées dans CSS, graphiques et configurations sans copies divergentes.</td></tr><tr><td>Réservation serveur</td><td><code>withIdempotentClaim</code> avec acquisition atomique, token de propriété, TTL et libération conditionnelle après échec.</td><td>Autoriser une nouvelle tentative sans retirer le bail d’un autre traitement.</td></tr><tr><td>Confirmation</td><td>Saisie exacte facultative dans <code>ConfirmDialog</code>, réinitialisation, libellés FR/EN et props du champ.</td><td>Renforcer les actions sensibles en gardant les permissions côté serveur.</td></tr><tr><td>Aperçu textuel</td><td><code>diffLines</code> borné, lignes ajoutées/retirées/inchangées et numéros avant/après.</td><td>Préparer une comparaison lisible avant application d’un changement, sans rendre du HTML actif.</td></tr></tbody></table><p>Une dépendance Vue directe a aussi été déclarée pour le site VitePress : elle permet la résolution du rendu serveur sous pnpm, sans ajouter Vue aux paquets publiés.</p><h2 id="deja-livre-et-reverifie" tabindex="-1">Déjà livré et revérifié <a class="header-anchor" href="#deja-livre-et-reverifie" aria-label="Permalink to &quot;Déjà livré et revérifié&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Brique</th><th>Mise à jour déjà disponible</th><th>Utilité</th></tr></thead><tbody><tr><td>Overlays, Select et Drawer</td><td>Sélections portalisées conservées dans le parent ; Échap ferme la couche active (0.12).</td><td>Utiliser des sélecteurs dans les tiroirs sans fermetures parasites.</td></tr><tr><td>Modal</td><td>Maintien du focus et du curseur avec callbacks inline (0.12).</td><td>Saisir sans perdre le focus après chaque caractère.</td></tr><tr><td>DataTable</td><td>Retour à la ligne des cartes, troncature configurable (0.12), actualisation configurable déjà livrée.</td><td>Lire les valeurs longues sur mobile et recharger les listes.</td></tr><tr><td>FileUpload</td><td>Sélection/dépôt de dossiers, chemins relatifs, lecture et annulation (0.12).</td><td>Importer une arborescence sans champ natif parallèle.</td></tr><tr><td>Permissions, formulaires, icônes</td><td><code>PermissionMatrix</code>, convention CRUD configurable, <code>renderControl</code> et icônes de console déjà exposés.</td><td>Réutiliser les briques disponibles ; leur adoption dans un consommateur reste une migration de ce consommateur.</td></tr></tbody></table><p>Ces migrations locales ne constituent pas de nouvelles fonctionnalités manquantes dans la bibliothèque.</p><h3 id="navigation-flottante-—-correction" tabindex="-1">Navigation flottante — correction <a class="header-anchor" href="#navigation-flottante-—-correction" aria-label="Permalink to &quot;Navigation flottante — correction&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Sidebar réduit : largeur de défilement et centrage des icônes</td><td>Éviter de rogner les icônes dans le rail flottant.</td></tr><tr><td>AppShell : retrait flottant unique, logo réduit et hauteur corrigée</td><td>Garder le logo et les actions de pied visibles sans doubler marges et padding.</td></tr><tr><td>Stories de régression et entrées sidebar/app-shell en 0.14.0</td><td>Vérifier la géométrie dans un navigateur et signaler la correction aux projets utilisant le registre.</td></tr></tbody></table><h2 id="premier-socle-natif-—-implemente-experimental" tabindex="-1">Premier socle natif — implémenté, expérimental <a class="header-anchor" href="#premier-socle-natif-—-implemente-experimental" aria-label="Permalink to &quot;Premier socle natif — implémenté, expérimental&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td><code>SiaNativeProvider</code>, <code>useNativeTheme</code>, thème CSS généré et Uniwind</td><td>Réutiliser la palette, les espacements et les formes SIA sans maintenir une copie mobile divergente ; suivre le thème système.</td></tr><tr><td><code>Text</code>, <code>Button</code>, <code>Input</code>, <code>Card</code></td><td>Composer des écrans natifs avec hiérarchie visuelle commune, cibles tactiles, chargement protégé et saisie stable.</td></tr><tr><td><code>Modal</code></td><td>Proposer une confirmation avec sortie interruptible, contenu défilant, zones sûres, clavier et demande de fermeture Android.</td></tr><tr><td><code>Toast</code></td><td>Donner un retour non bloquant ; suspendre le délai en arrière-plan ou avec lecteur d’écran pour laisser le temps de lire.</td></tr><tr><td><code>Animated</code> et tokens de mouvement</td><td>Harmoniser appui, focus, apparitions et sorties ; respecter la réduction des animations du système.</td></tr><tr><td>Démo Expo officielle et formulaire headless local</td><td>Vérifier les briques ensemble sans backend ; lancer et exporter depuis la racine avec <code>pnpm native</code> / <code>pnpm native:export</code>.</td></tr><tr><td>Tests natifs de comportement et compilation Metro</td><td>Détecter les régressions de callbacks, états, délais et compatibilité du premier lot.</td></tr></tbody></table><p>Le compilateur TypeScript de la documentation est désormais déclaré explicitement pour conserver la version du workspace lorsque la démo Expo installe TypeScript 6.</p><h3 id="formulaires-et-selection-mobile-—-deuxieme-lot-implemente" tabindex="-1">Formulaires et sélection mobile — deuxième lot implémenté <a class="header-anchor" href="#formulaires-et-selection-mobile-—-deuxieme-lot-implemente" aria-label="Permalink to &quot;Formulaires et sélection mobile — deuxième lot implémenté&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Checkbox, Switch SIA et RadioGroup contrôlés</td><td>Accords, préférences et choix exclusifs accessibles, avec états désactivés et descriptions.</td></tr><tr><td>PasswordInput et Input.endAdornment</td><td>Afficher/masquer le mot de passe depuis une action intégrée, sans remonter le champ.</td></tr><tr><td>FormContainer et FormSection</td><td>Structurer les formulaires, réutiliser FormAdapter, gérer clavier/défilement et centraliser les actions.</td></tr><tr><td>Verrou d’envoi et gestion des exceptions</td><td>Bloquer les doubles envois dès la validation asynchrone, y compris depuis le clavier ; montrer une erreur lisible sans détail technique.</td></tr><tr><td>Messages de champ et résumé explicitement rouges</td><td>Identifier les erreurs dans les thèmes clair/sombre, avec message et annonce d’accessibilité.</td></tr><tr><td>BottomSheet et primitives communes de Modal</td><td>Présenter une feuille avec zones sûres, clavier, Retour et fermeture par la poignée, sans gêner le défilement du contenu.</td></tr><tr><td>Select avec recherche locale et FlatList</td><td>Choisir dans une seule interface de recherche, filtrer sans accents, gérer options désactivées, chargement et absence de résultat.</td></tr><tr><td>Démo Expo : connexion migrée et formulaire par sections</td><td>Tester ensemble saisie, choix, consentement, validation et actions, sans backend.</td></tr></tbody></table><h3 id="switch-mobile-—-identite-visuelle-sia" tabindex="-1">Switch mobile — identité visuelle SIA <a class="header-anchor" href="#switch-mobile-—-identite-visuelle-sia" aria-label="Permalink to &quot;Switch mobile — identité visuelle SIA&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Piste arrondie et pouce contrasté, avec repères marche/arrêt</td><td>Conserver la même identité sur Android/iOS et lire l’état sans se fier uniquement à la couleur.</td></tr><tr><td>Tailles sm/md/lg et ligne entièrement tactile d’au moins 48 unités</td><td>Adapter la densité sans réduire la zone d’appui ; permettre aussi de toucher le libellé.</td></tr><tr><td>Déplacement avec rebond, retour d’appui et mouvement réduit</td><td>Donner un retour cohérent avec les tokens SIA et les préférences d’accessibilité.</td></tr><tr><td>Focus visible, erreurs rouges et état désactivé</td><td>Garder le contrôle utilisable au clavier et dans les formulaires, sans double élément accessible.</td></tr><tr><td>Contrat Pressable avec checked/onCheckedChange</td><td>Piloter l’interaction personnalisée ; remplacer les événements propres au Switch système.</td></tr></tbody></table><h3 id="navigation-session-et-personnalisation-mobiles-—-implemente" tabindex="-1">Navigation, session et personnalisation mobiles — implémenté <a class="header-anchor" href="#navigation-session-et-personnalisation-mobiles-—-implemente" aria-label="Permalink to &quot;Navigation, session et personnalisation mobiles — implémenté&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Fond du tiroir bord à bord, zones sûres internes et modale Android translucide</td><td>Supprimer les bandes vides en haut et en bas tout en protégeant les commandes de l’encoche et de la navigation système.</td></tr><tr><td>Tiroir avec en-tête unique, largeur contenue et Stack racine sans en-tête par défaut</td><td>Éviter le cumul de barres de navigation et le débordement de la variante flottante sur mobile.</td></tr><tr><td>Barre basse avec capsule, trait ou sélection minimale, badges chiffrés et icônes vectorielles dans la démo</td><td>Améliorer la hiérarchie visuelle et garder des icônes cohérentes sur les téléphones.</td></tr><tr><td>Styles, couleurs, densité et rendus des onglets personnalisables</td><td>Adapter la navigation à une marque sans réécrire les permissions, les noms accessibles ni le menu Plus.</td></tr><tr><td>Animations des onglets configurables et options du Stack privé exposées</td><td>Choisir ressort, durée, courbe, échelle, élévation et transitions entre pages tout en respectant la réduction des animations.</td></tr><tr><td>Réglages de barre basse, couleurs et animations persistés dans la démo</td><td>Comparer les variantes et ajuster le rendu sur appareil depuis le panneau Personnaliser.</td></tr><tr><td>BottomBar avec Plus, Sidebar hiérarchique, rail et tiroir</td><td>Réutiliser une navigation mobile cohérente, garder les destinations accessibles et adapter la disposition à l’écran.</td></tr><tr><td>AppShell avec slots, variantes, largeur et mode configurables</td><td>Assembler l’application sans réécrire le layout, les zones sûres et les ouvertures de navigation ; conserver les saisies quand la disposition change.</td></tr><tr><td>RequireSession relié au SessionStore existant</td><td>Attendre l’hydratation, vérifier les droits et refuser le montage prématuré d’un écran privé sans dupliquer la session.</td></tr><tr><td>Entrée Expo Router : SiaExpoStack, SiaExpoLayout, useExpoSessionReturn</td><td>Déduire la route active, gérer les accès directs et redirections, reprendre une adresse interne et retirer l’historique privé après déconnexion.</td></tr><tr><td>StateScreen et routes de démonstration 404/erreur/profil</td><td>Fournir des écrans de récupération avec action, en gardant les textes personnalisables.</td></tr><tr><td>Palettes locales et NativeThemeScope</td><td>Changer les couleurs en gardant classes, valeurs inline et portails cohérents, sans mutation d’un thème global.</td></tr><tr><td>Démo à pages Expo Router et panneau Personnaliser</td><td>Essayer les modes de navigation, le rail, les couleurs et les états de session depuis une application complète ; conserver les préférences localement.</td></tr></tbody></table><p><strong>Restant :</strong> essais de ces nouveaux parcours sur appareils, liens profonds natifs, Retour, focus et lecteurs d’écran ; gestes avancés et parcours métier. La démo est locale et ne remplace pas un backend d’authentification. Voir le <a href="./../guides/navigation-mobile-expo-router.html">guide navigation/session</a>.</p><h2 id="hors-perimetre-et-limites-explicites" tabindex="-1">Hors périmètre et limites explicites <a class="header-anchor" href="#hors-perimetre-et-limites-explicites" aria-label="Permalink to &quot;Hors périmètre et limites explicites&quot;">​</a></h2><ul><li><strong>Expérimental :</strong> premier lot React Native avec Uniwind ; validation sur appareils et extension du catalogue encore prévues.</li><li>Le broker, le journal durable et les règles d’autorisation sont des adaptateurs de l’application ; aucune instance Redis n’est provisionnée.</li><li>La présence distribuée et un journal transactionnel ne sont pas annoncés comme livrés.</li><li><code>diffLines</code> n’ajoute pas un composant visuel de comparaison et ne retire pas les secrets à la place de l’application.</li></ul><p>Les comportements et leurs limites sont décrits dans <a href="./../guides/temps-reel-et-attente.html">Temps réel et attente</a> et <a href="./../fondations/utilitaires-operationnels.html">Utilitaires opérationnels</a>.</p><h2 id="matrice-de-couverture-web-et-mobile-—-documentation-livree" tabindex="-1">Matrice de couverture web et mobile — documentation livrée <a class="header-anchor" href="#matrice-de-couverture-web-et-mobile-—-documentation-livree" aria-label="Permalink to &quot;Matrice de couverture web et mobile — documentation livrée&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Inventaire des 115 modules publics web, avec équivalents natifs, statuts et écarts explicites</td><td>Distinguer composant disponible, couverture partielle et travail à réaliser ; éviter de confondre une démo ou un hook avec un composant livré.</td></tr><tr><td>Priorités proposées pour Steps, Tabs, BottomSheet avancée, états, formulaires et parcours métier</td><td>Organiser les prochains incréments autour des usages mobiles sans reproduire systématiquement les interactions de bureau.</td></tr><tr><td>Distinction entre compilation et validation sur appareils</td><td>Garder visibles les essais Android/iOS restant à faire ; ne pas présenter cette matrice comme une certification du rendu natif.</td></tr></tbody></table><p>Voir la <a href="./parite-web-mobile.html">matrice complète</a>. Cette mise à jour est documentaire : elle n’ajoute aucun composant natif. Les lots V et L1–L5 sont des priorités proposées, pas des fonctionnalités déjà implémentées ni un calendrier de livraison.</p><h2 id="presentation-et-organisation-mobiles-—-lot-implemente" tabindex="-1">Présentation et organisation mobiles — lot implémenté <a class="header-anchor" href="#presentation-et-organisation-mobiles-—-lot-implemente" aria-label="Permalink to &quot;Présentation et organisation mobiles — lot implémenté&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Badge, Avatar, Alert, Spinner, Skeleton, Progress et Divider</td><td>Composer messages, chargements, statuts et fiches avec les mêmes couleurs SIA, sans redessiner ces états dans chaque application.</td></tr><tr><td>IconButton, parties Card et nouvelles variantes Text</td><td>Garder des cartes composables, des actions nommées pour l’accessibilité et une hiérarchie de contenu adaptée au téléphone.</td></tr><tr><td>Steps</td><td>Afficher les étapes, leurs états et une navigation contrôlée ; le formulaire garde ses validations et règles de progression.</td></tr><tr><td>Tabs de contenu et Accordion</td><td>Organiser les écrans sans longues pages uniformes ; conserver les enfants et leurs saisies lorsque les panneaux sont masqués.</td></tr><tr><td>Toaster branché sur le store partagé</td><td>Utiliser les notifications évolutives, actions et placements existants, sans nouvelle API métier ; suspendre les délais en arrière-plan et avec lecteur d’écran.</td></tr><tr><td>BottomSheet à positions contrôlées/locales avec poignée et actions d’accessibilité</td><td>Redimensionner une feuille sans prendre les gestes de la liste ; borner la hauteur et régler la durée de transition.</td></tr><tr><td>Défauts locaux lus par Button et les nouveaux composants configurables</td><td>Définir un rendu commun dans une section tout en donnant priorité aux props explicites.</td></tr><tr><td>Catalogue de démonstration par familles et onglets principaux épinglés</td><td>Retrouver les exemples sans parcourir une galerie trop longue ; conserver une navigation courte sur mobile et une hiérarchie sur tablette.</td></tr></tbody></table><p>Restant : validation native des gestes, clavier, focus et lecteurs d’écran ; flèches/Home/End des Tabs ; généralisation des defaults ; BottomSheet déplacée sur tout le contenu. L’adaptation de hauteur au clavier est traitée dans le lot Formulaires ci-dessous. Aucun test de compilation ne vaut validation de ces comportements sur appareil. Voir le <a href="./../guides/composants-mobiles.html">guide du lot</a> et la <a href="./parite-web-mobile.html">matrice actualisée</a>.</p><h2 id="transitions-de-contenu-et-prise-du-geste-de-feuille-—-correction-implementee" tabindex="-1">Transitions de contenu et prise du geste de feuille — correction implémentée <a class="header-anchor" href="#transitions-de-contenu-et-prise-du-geste-de-feuille-—-correction-implementee" aria-label="Permalink to &quot;Transitions de contenu et prise du geste de feuille — correction implémentée&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Remplissage déterminé de Progress animé et interruptible</td><td>Voir l’évolution de la progression et repartir de la largeur affichée lors de changements rapides, y compris en arrière.</td></tr><tr><td>Connecteurs, repères et changements de statut de Steps animés</td><td>Rendre lisible le passage d’une étape à l’autre, avec des connecteurs adaptés à l’orientation.</td></tr><tr><td>Apparition des panneaux Tabs en fondu/glissement, sans remontage des champs</td><td>Percevoir le changement de vue tout en conservant les saisies ; désactivation locale ou mouvement réduit possible.</td></tr><tr><td>NativeTransitionOptions et réglages persistés de la démo</td><td>Régler durée, courbe et désactivation par composant/provider ; distinguer mouvement des pages et du contenu.</td></tr><tr><td>Poignée de feuille propriétaire du geste dès le contact et départ à la hauteur affichée</td><td>Éviter qu’un parent détourne le geste ou qu’une transition/mise à jour ramène la feuille pendant le déplacement ; garder le défilement de la liste séparé.</td></tr></tbody></table><p>La validation inclut des changements rapides et un geste tactile avec mesure de hauteur pendant le déplacement. La confirmation Android/iOS sur téléphone reste nécessaire ; le glissement sur tout le contenu n’est pas ajouté par cette correction.</p><h2 id="spinner-natif-—-variantes-completes-implementees" tabindex="-1">Spinner natif — variantes complètes implémentées <a class="header-anchor" href="#spinner-natif-—-variantes-completes-implementees" aria-label="Permalink to &quot;Spinner natif — variantes complètes implémentées&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Dessins ring, double-ring et dots ; tailles xs/sm/md/lg/xl</td><td>Retrouver les variantes et tailles du web avec une identité SIA stable sur Android/iOS.</td></tr><tr><td>Tons, couleur explicite et contexte current ; valeurs par défaut locales</td><td>Adapter l’indicateur à un thème ou à un bouton sans dépendre d’un héritage CSS inexistant dans une View native.</td></tr><tr><td>Durée, épaisseur et arrêt des animations ; pause en arrière-plan et mouvement réduit</td><td>Personnaliser le dessin et éviter les boucles inutiles tout en conservant l’annonce de chargement.</td></tr><tr><td>Spinner réutilisé par Button, StateScreen et Toaster ; page de comparaison</td><td>Vérifier les quinze combinaisons variante/taille et garder les indicateurs cohérents dans l’application.</td></tr></tbody></table><h2 id="formulaires-natifs-et-clavier-—-implemente" tabindex="-1">Formulaires natifs et clavier — implémenté <a class="header-anchor" href="#formulaires-natifs-et-clavier-—-implemente" aria-label="Permalink to &quot;Formulaires natifs et clavier — implémenté&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Form, Field/FormField, groupes, validation configurable et références stables</td><td>Déclarer un formulaire sans réécrire la liaison valeurs/erreurs ni perdre le focus à chaque frappe.</td></tr><tr><td>Apparences outline/filled/underline, tailles sm/md/lg, erreurs rouges et lecture seule</td><td>Adapter la densité et distinguer consultation, verrou et erreur dans un même langage visuel.</td></tr><tr><td>Select distant, MultiSelect et Autocomplete avec annulation, cache des libellés et réessai</td><td>Sélectionner une ou plusieurs ressources sans ajouter un second champ de recherche.</td></tr><tr><td>InputNumber, CurrencyInput, PhoneInput, OtpInput, Textarea et SearchInput</td><td>Conserver les saisies intermédiaires et proposer des interactions adaptées au type de donnée.</td></tr><tr><td>Premier invalide, chaîne Suivant/Terminé, barre clavier et compensation partagée</td><td>Rendre le parcours utilisable sans masquer le contrôle actif ou doubler les décalages dans une feuille.</td></tr><tr><td>Feuille agrandie avec le clavier puis retour à la hauteur configurée</td><td>Donner de la place aux champs sans perdre les positions de repos.</td></tr><tr><td>ConfirmDialog asynchrone et garde de sortie Expo optionnel</td><td>Éviter les doubles actions et demander confirmation avant de perdre une saisie.</td></tr><tr><td>Démo organisée : manuel, déclaratif, sélections, variantes et confirmation</td><td>Essayer les états, dimensions, erreurs simulées et différents modes de saisie dans des pages identifiables.</td></tr></tbody></table><p>Restant : essais clavier/IME et accessibilité sur téléphones, pagination distante, sélecteur de pays, OTP en cases et autres champs avancés. Le lot dates/fichiers est décrit plus bas. Voir le <a href="./../guides/formulaires-declaratifs-mobiles.html">guide précis des APIs et limites</a>.</p><h2 id="visibilite-des-champs-au-clavier-—-correction-implementee" tabindex="-1">Visibilité des champs au clavier — correction implémentée <a class="header-anchor" href="#visibilite-des-champs-au-clavier-—-correction-implementee" aria-label="Permalink to &quot;Visibilité des champs au clavier — correction implémentée&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Mesure du champ et du viewport après focus, ouverture/redimensionnement du clavier et apparition de la barre</td><td>Positionner la saisie dans l’espace réellement visible plutôt qu’avec un décalage fixe.</td></tr><tr><td>Défilement borné, repositionnement dans les deux directions et rejet des mesures tardives</td><td>Retrouver le champ précédent sans saut vers un ancien champ lors de changements rapides.</td></tr><tr><td>Chevrons Précédent/Suivant avec noms accessibles et cibles de 48 unités</td><td>Réduire la largeur de la barre tout en conservant son usage tactile et avec lecteur d’écran.</td></tr><tr><td>KeyboardScrollView et focus Input partagé ; correction des exemples manuels/variantes</td><td>Utiliser le même mécanisme dans une page libre et éviter les défilements imbriqués sans compensation clavier.</td></tr></tbody></table><p>Les tests simulent clavier, changement de viewport et réponses de mesure retardées. La vérification de l’IME et du rendu physique Android/iOS reste à faire sur appareil.</p><h2 id="dates-et-fichiers-natifs-—-implemente" tabindex="-1">Dates et fichiers natifs — implémenté <a class="header-anchor" href="#dates-et-fichiers-natifs-—-implemente" aria-label="Permalink to &quot;Dates et fichiers natifs — implémenté&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Calendar tactile, année recherchable, jours bloqués et fondu configurable</td><td>Choisir un jour rapidement dans l’identité SIA, avec bornes et mouvement réduit.</td></tr><tr><td>DatePicker, DateRangePicker, TimePicker et DateTimePicker avec brouillon</td><td>Confirmer un jour, une période ou un rendez-vous sans modifier la valeur lors d’une fermeture.</td></tr><tr><td>Valeurs civiles, validation stricte, formats 12/24 h et bornes date/heure</td><td>Éviter les décalages UTC implicites et les valeurs impossibles ou hors limites.</td></tr><tr><td>FileUpload/ImageUpload et adaptateur mutualisé, modules Expo officiels dans la démo</td><td>Sélectionner documents, photothèque ou caméra sans coupler le cœur à Expo.</td></tr><tr><td>Contrôles type/taille/nombre, aperçu et retrait ; annulation et résultats tardifs ignorés</td><td>Garder une sélection cohérente, présenter les refus et éviter les doublons après réessai.</td></tr><tr><td>Nouveaux types Form/Field et références de déclencheurs</td><td>Réutiliser validation et focus existants pour dates, heures et pièces jointes.</td></tr><tr><td>Contexte de défilement isolé dans les modales</td><td>Éviter qu’une recherche imbriquée déplace le formulaire situé derrière, tout en permettant un formulaire interne autonome.</td></tr><tr><td>Deux pages de démo avec variantes, états et refus simulé</td><td>Vérifier les contraintes et permissions sans confondre sélection locale et transfert serveur.</td></tr></tbody></table><p>Restant : validations physiques des permissions/caméra et accessibilité ; transfert et progression réseau, recadrage, fuseaux métier et import de dossiers non inclus. Voir le <a href="./../guides/dates-fichiers-mobiles.html">guide complet</a>.</p><h2 id="actions-de-date-et-rouleaux-horaires-—-correction-implementee" tabindex="-1">Actions de date et rouleaux horaires — correction implémentée <a class="header-anchor" href="#actions-de-date-et-rouleaux-horaires-—-correction-implementee" aria-label="Permalink to &quot;Actions de date et rouleaux horaires — correction implémentée&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Aujourd’hui déplacé dans le pied fixe des sélecteurs</td><td>Garder le raccourci accessible même lorsque le calendrier ou le rendez-vous dépasse la zone visible.</td></tr><tr><td>Rouleaux heures/minutes et AM/PM en format 12 h</td><td>Choisir l’heure directement par glissement, sans ouvrir un Select pour chaque partie.</td></tr><tr><td>Alignement central, boucle configurable, valeurs bloquées ignorées et minute hors pas conservée</td><td>Stabiliser la sélection lors des gestes et respecter les contraintes sans arrondi silencieux.</td></tr><tr><td>Trois/cinq lignes, actions accessibles, flèches clavier et mouvement réduit</td><td>Adapter la présentation à l’écran et aux moyens d’interaction ; réglages disponibles dans la démo.</td></tr></tbody></table><p>Restant : validation tactile et inertie sur téléphone ; aucune validation physique n’est déduite des tests ou des exports.</p><h2 id="mois-complet-sans-defilement-—-correction-implementee" tabindex="-1">Mois complet sans défilement — correction implémentée <a class="header-anchor" href="#mois-complet-sans-defilement-—-correction-implementee" aria-label="Permalink to &quot;Mois complet sans défilement — correction implémentée&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour</th><th>Utilité</th></tr></thead><tbody><tr><td>Choix de l’année intégré à l’en-tête compact du calendrier</td><td>Libérer la hauteur occupée par un champ Année séparé tout en conservant sa recherche et son nom accessible.</td></tr><tr><td>Grille calculée à partir de la hauteur mesurée et du nombre réel de semaines</td><td>Garder tous les jours du mois visibles, y compris la sixième semaine, sans ScrollView interne.</td></tr><tr><td>Feuille compacte et actions Aujourd’hui/Confirmer fixes</td><td>Réduire les marges sans masquer les actions ni retirer la poignée.</td></tr><tr><td>Vues Date/Heure du rendez-vous avec brouillon commun</td><td>Donner toute la zone au calendrier ou aux rouleaux, en conservant les choix entre les deux vues.</td></tr><tr><td>labelHidden, density et fill sur les briques communes</td><td>Permettre ce format contraint sans modifier les réglages des autres sélections, feuilles et panneaux.</td></tr></tbody></table><p>Les tests couvrent la sixième semaine, l’accès au choix d’année et la conservation du rendez-vous. Les essais sur appareils restent nécessaires pour les zones sûres, les grandes polices et les lecteurs d’écran.</p><h2 id="listes-et-parcours-metier-natifs-—-implemente-prochaine-publication" tabindex="-1">Listes et parcours métier natifs — implémenté, prochaine publication <a class="header-anchor" href="#listes-et-parcours-metier-natifs-—-implemente-prochaine-publication" aria-label="Permalink to &quot;Listes et parcours métier natifs — implémenté, prochaine publication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mise à jour exacte</th><th>Utilité</th></tr></thead><tbody><tr><td>Contrats <code>ResourceDefinitionCore</code>, <code>ResourceDataSource</code>, routes et permissions extraits dans headless ; réexports web conservés</td><td>Partager les métadonnées sans imposer les contrôles DOM au mobile.</td></tr><tr><td><code>useResourcePage</code> / <code>useResourceDetail</code>, annulation, dernière réponse gagnante et recherche temporisée</td><td>Éviter les anciennes données après une recherche ou un changement de fiche.</td></tr><tr><td><code>ResourceList</code> virtualisée, cartes/lignes, deux densités, tri direct, tailles de page, pagination compacte/numérotée et actualisation configurable</td><td>Consulter une collection sur téléphone sans charger toutes les lignes dans la vue.</td></tr><tr><td><code>FiltersBar</code>, filtres en feuille, validation/annulation et résumé actif</td><td>Chercher et filtrer sans multiplier les champs permanents.</td></tr><tr><td><code>CrudPage</code>, fiche, création/édition dérivées, DTO personnalisables et suppression confirmée</td><td>Assembler un parcours métier complet depuis une définition et un adaptateur de données.</td></tr><tr><td><code>ResourceValidationError</code>, erreurs de champs et conservation de la saisie après échec</td><td>Corriger une erreur serveur sans remplir de nouveau le formulaire.</td></tr><tr><td><code>PageHeader</code>, <code>Descriptions</code>, <code>AsyncState</code>, <code>PermissionGate</code> et réévaluation des droits avant écriture</td><td>Réutiliser les états de page et refuser les opérations non autorisées.</td></tr><tr><td>Formulaires reliés au clavier existant et protection des saisies non enregistrées ; garde Expo injectable</td><td>Garder les contrôles accessibles et éviter la perte de modifications en revenant en arrière.</td></tr><tr><td>Démo Contacts avec routes Expo, stockage local, compte membre/administrateur et simulations</td><td>Tester création, édition, suppression, attente, vide, erreur et lecture seule sur un même exemple.</td></tr></tbody></table><p>Restent prévus : tableau multicolonnes tablette, actions en masse, curseurs/chargement infini, cache temps réel et briques métier complémentaires. Les essais physiques Android/iOS restent nécessaires ; aucune publication npm n&#39;est faite par ce changement.</p>',52)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
